/**
 * GENERATED FILE PRODUCER — writes lib/geometry/__fixtures__/phase17-channel-litres-today.json: the litres of the 49
 * channelled boards (`phase17ChannelBoards`, lib/geometry/__fixtures__/phase17-channel-boards.ts) exactly as the app
 * reads them TODAY, under the live rules. Unlike extract-phase17-channel-litres-pin.ts (a one-time record of the code as
 * it stood before the channels were cut straight up into the finished rail, 17-19, never re-run), this script may be
 * run again whenever a starter board or the litres' maths changes on purpose — the test
 * (lib/geometry/phase17-channel-litres.test.ts) holds every board to this record to the last digit, so a change that
 * moves a channelled board's litres fails until the record is made again, and the diff shows every figure that moved.
 *
 *   npx --no-install tsx --tsconfig ./tsconfig.json scripts/extract-phase17-channel-litres-today.ts
 *
 * run from the repository root. (Nothing in package.json — `--no-install` means npx can only run the tsx already in
 * node_modules. No database.) The output is generated and must never be hand-edited.
 *
 * Each figure is `summarizeDesign(fields).volumeLitres.toPrecision(17)`, a string, so the test compares every digit a
 * double holds.
 */
import { execSync } from "node:child_process";
import { existsSync, writeFileSync } from "node:fs";
import path from "node:path";
import { phase17ChannelBoards } from "@/lib/geometry/__fixtures__/phase17-channel-boards";
import { summarizeDesign } from "@/lib/geometry/design";

const VOLUME = path.resolve(process.cwd(), "lib/geometry/volume.ts");
const OUTPUT = path.resolve(process.cwd(), "lib/geometry/__fixtures__/phase17-channel-litres-today.json");

function headCommit(): string {
  try {
    return execSync("git rev-parse --short=8 HEAD", { encoding: "utf8" }).trim();
  } catch {
    return "unknown";
  }
}

function main() {
  if (!existsSync(VOLUME)) {
    throw new Error("Run this from the repository root (lib/geometry/volume.ts not found here).");
  }
  const litres: Record<string, string> = {};
  for (const board of phase17ChannelBoards()) {
    litres[board.label] = summarizeDesign(board.fields).volumeLitres.toPrecision(17);
  }
  const provenance =
    "GENERATED by scripts/extract-phase17-channel-litres-today.ts from the app's live rules (phase17ChannelBoards, " +
    `summarizeDesign, toPrecision(17); commit ${headCommit()}, ${new Date().toISOString().slice(0, 10)}) — never hand-edit; ` +
    "re-run the script when a channelled board's litres are meant to move";
  writeFileSync(OUTPUT, `${JSON.stringify({ provenance, litres }, null, 2)}\n`);
  for (const [label, value] of Object.entries(litres)) console.log(`${label}: ${Number(value).toFixed(4)} L`);
  console.log(`wrote ${path.relative(process.cwd(), OUTPUT)} (${Object.keys(litres).length} boards)`);
}

try {
  main();
} catch (error: unknown) {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
}
